"""Offline contract tests for building the supplemental third-party license evidence directory."""
import hashlib
import io
import json
from pathlib import Path
import subprocess
import sys
import tarfile
import tempfile
import unittest
import zipfile

ROOT = Path(__file__).resolve().parents[1]
SCRIPT = Path(__file__).with_name('build-third-party-licenses.py')
MANIFEST = 'scripts/third-party-license-sources.json'
MANUAL = 'scripts/third-party-notices.manual.json'
OUT = 'scripts/third-party-licenses'

HEADER = b'/*\n * Copyright 2026 Example Authors.\n * Licensed under the Example License.\n */'
A_JAVA = (HEADER + b'\npackage a;\n\nclass A {\n'
          b'  String s = "/* Copyright inside a string literal */";\n'
          b'  char c = \'"\';\n'
          b'  // This method was taken from elsewhere\n'
          b'  // Copyright (C) 2012 Somebody\n'
          b'  void m() {}\n'
          b'  /** Returns nothing interesting. */\n'
          b'}\n')
B_JAVA = HEADER + b'\npackage a;\n\n/** Algorithm based on a published paper. */\nclass B {}\n'
LINE_RUN = b'// This method was taken from elsewhere\n  // Copyright (C) 2012 Somebody'
BASED_ON = b'/** Algorithm based on a published paper. */'
C_HEADER = b'/* Copyright (c) 2026 C Authors */'
OTHER_C_HEADER = b'/* Copyright (c) 2025 Other Authors */'


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def git_blob(data):
    return hashlib.sha1(b'blob %d\0' % len(data) + data).hexdigest()


class BuildTest(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.repo = Path(self.temp.name) / 'repo'
        self.upstream = Path(self.temp.name) / 'upstream'
        (self.repo / 'scripts').mkdir(parents=True)
        self.upstream.mkdir()
        self.documents = []
        self.archives = []
        self.profiles = {
            'jvm': {'extensions': ['.java'], 'comments': ['block', 'line'], 'pattern': 'copyright|licen[cs]e|based on',
                    'order': 'archive', 'entryHeaders': True},
            'c': {'scope': 'Library sources only.', 'extensions': ['.c', '.h'], 'pathPrefixes': ['lib/'],
                  'stripComponents': 1, 'comments': ['block'], 'pattern': 'copyright', 'order': 'sha256',
                  'entryHeaders': False},
        }

    def upstream_file(self, name, data):
        path = self.upstream / name
        path.write_bytes(data)
        return path.as_uri()

    def jar(self, name, entries):
        buffer = io.BytesIO()
        with zipfile.ZipFile(buffer, 'w') as archive:
            for entry, data in entries:
                archive.writestr(entry, data)
        url = self.upstream_file(name, buffer.getvalue())
        self.archives.append({'id': name, 'url': url, 'sha256': sha256(buffer.getvalue())})
        return url

    def tarball(self, name, entries):
        buffer = io.BytesIO()
        with tarfile.open(fileobj=buffer, mode='w:gz') as archive:
            for entry, data in entries:
                info = tarfile.TarInfo(entry)
                info.size = len(data)
                archive.addfile(info, io.BytesIO(data))
        url = self.upstream_file(name, buffer.getvalue())
        self.archives.append({'id': name, 'url': url, 'sha256': sha256(buffer.getvalue())})
        return url

    def document(self, path, expected, source, **recipe):
        self.documents.append({'path': OUT + '/' + path, 'sha256': sha256(expected), 'source': source, **recipe})

    def write_manifest(self):
        manifest = {'schemaVersion': 1, 'outputDirectory': OUT, 'profiles': self.profiles,
                    'archives': self.archives, 'documents': self.documents}
        (self.repo / MANIFEST).write_text(json.dumps(manifest, indent=2) + '\n')

    def run_script(self, *arguments):
        self.write_manifest()
        return subprocess.run([sys.executable, str(SCRIPT), '--repo', str(self.repo), *arguments],
                              capture_output=True, text=True)

    def output(self, path):
        return (self.repo / OUT / path).read_bytes()

    def test_copies_plain_sources_and_archive_entries_verbatim(self):
        license_text = b'Example License\r\nline two\n'
        self.document('example.txt', license_text, self.upstream_file('LICENSE', license_text))
        jar = self.jar('a-sources.jar', [('a/A.java', A_JAVA)])
        self.document('a-1.0/A.java.txt', A_JAVA, jar + '!/a/A.java')
        result = self.run_script()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(self.output('example.txt'), license_text)
        self.assertEqual(self.output('a-1.0/A.java.txt'), A_JAVA)
        self.assertEqual(self.run_script('--check').returncode, 0)

    def test_hash_mismatch_fails_without_writing_anything(self):
        self.document('good.txt', b'good', self.upstream_file('good', b'good'))
        self.document('bad.txt', b'expected', self.upstream_file('bad', b'tampered'))
        result = self.run_script()
        self.assertEqual(result.returncode, 1)
        self.assertIn(OUT + '/bad.txt', result.stderr)
        self.assertFalse((self.repo / OUT).exists())

    def test_archive_hash_mismatch_fails(self):
        jar = self.jar('a-sources.jar', [('a/A.java', A_JAVA)])
        self.archives[0]['sha256'] = '0' * 64
        self.document('a-1.0/A.java.txt', A_JAVA, jar + '!/a/A.java')
        result = self.run_script()
        self.assertEqual(result.returncode, 1)
        self.assertIn('a-sources.jar', result.stderr)
        self.assertFalse((self.repo / OUT).exists())

    def test_unpinned_archive_is_rejected(self):
        jar = self.jar('a-sources.jar', [('a/A.java', A_JAVA)])
        self.archives.clear()
        self.document('a-1.0/A.java.txt', A_JAVA, jar + '!/a/A.java')
        result = self.run_script()
        self.assertEqual(result.returncode, 2)
        self.assertIn('not listed in archives', result.stderr)

    def test_source_notices_for_jvm_sources(self):
        jar = self.jar('a-sources.jar', [('a/A.java', A_JAVA), ('a/B.java', B_JAVA), ('a/notes.txt', HEADER)])
        notices = (b'Source entries: a/A.java#L1-L4, a/B.java#L1-L4\n' + HEADER + b'\n\n'
                   b'Source entries: a/A.java#L10-L11\n' + LINE_RUN + b'\n\n'
                   b'Source entries: a/B.java#L7-L7\n' + BASED_ON + b'\n\n')
        line_start = A_JAVA.index(LINE_RUN)
        based_start = B_JAVA.index(BASED_ON)
        origins = {'sourceArchive': jar, 'archiveSha256': self.archives[0]['sha256'], 'blocks': [
            {'commentSha256': sha256(HEADER), 'sources': [
                {'entry': 'a/A.java', 'sourceSha256': sha256(A_JAVA), 'startByte': 0, 'endByteExclusive': len(HEADER),
                 'startLine': 1, 'endLine': 4},
                {'entry': 'a/B.java', 'sourceSha256': sha256(B_JAVA), 'startByte': 0, 'endByteExclusive': len(HEADER),
                 'startLine': 1, 'endLine': 4}]},
            {'commentSha256': sha256(LINE_RUN), 'sources': [
                {'entry': 'a/A.java', 'sourceSha256': sha256(A_JAVA), 'startByte': line_start,
                 'endByteExclusive': line_start + len(LINE_RUN), 'startLine': 10, 'endLine': 11}]},
            {'commentSha256': sha256(BASED_ON), 'sources': [
                {'entry': 'a/B.java', 'sourceSha256': sha256(B_JAVA), 'startByte': based_start,
                 'endByteExclusive': based_start + len(BASED_ON), 'startLine': 7, 'endLine': 7}]}]}
        origins_bytes = (json.dumps(origins, indent=2) + '\n').encode()
        self.document('a-1.0/source-notices.txt', notices, jar, recipe='source-notices', profile='jvm')
        self.document('a-1.0/source-notice-origins.json', origins_bytes, jar, recipe='source-notice-origins',
                      profile='jvm')
        result = self.run_script()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(self.output('a-1.0/source-notices.txt'), notices)
        self.assertEqual(self.output('a-1.0/source-notice-origins.json'), origins_bytes)

    def test_source_notices_for_scoped_library_tarball(self):
        entries = [('pkg-1.0/lib/x.c', C_HEADER + b'\nint x; // Copyright line comments are out of scope\n'),
                   ('pkg-1.0/lib/y.h', OTHER_C_HEADER + b'\n/* no notice here */\n'),
                   ('pkg-1.0/tests/t.c', b'/* Copyright (c) 2026 Test Authors */\n'),
                   ('pkg-1.0/lib/readme.md', b'/* Copyright (c) 2026 Docs */\n')]
        tar = self.tarball('pkg-1.0.tar.gz', entries)
        blocks = sorted([C_HEADER, OTHER_C_HEADER], key=sha256)
        notices = b'\n\n'.join(blocks) + b'\n'
        self.document('pkg-1.0/source-notices.txt', notices, tar, recipe='source-notices', profile='c')
        result = self.run_script()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(self.output('pkg-1.0/source-notices.txt'), notices)

    def test_origins_for_tarball_record_scope_and_hash_order(self):
        tar = self.tarball('pkg-1.0.tar.gz', [('pkg-1.0/lib/x.c', C_HEADER + b'\n'),
                                              ('pkg-1.0/lib/y.h', OTHER_C_HEADER + b'\n'),
                                              ('pkg-1.0/COPYING', b'license')])
        self.document('pkg-1.0/COPYING.txt', b'license', tar + '!/pkg-1.0/COPYING')
        self.documents.append({'path': OUT + '/pkg-1.0/source-notice-origins.json', 'sha256': '0' * 64, 'source': tar,
                               'recipe': 'source-notice-origins', 'profile': 'c'})
        result = self.run_script('--update-hashes')
        self.assertEqual(result.returncode, 0, result.stderr)
        origins = json.loads(self.output('pkg-1.0/source-notice-origins.json'))
        self.assertEqual(list(origins), ['sourceArchive', 'archiveSha256', 'scope', 'blocks'])
        self.assertEqual(origins['scope'], 'Library sources only.')
        hashes = [block['commentSha256'] for block in origins['blocks']]
        self.assertEqual(hashes, sorted([sha256(C_HEADER), sha256(OTHER_C_HEADER)]))
        self.assertEqual(self.output('pkg-1.0/COPYING.txt'), b'license')

