    def test_update_hashes_rewrites_manifest_and_manual_inventory(self):
        jar = self.jar('a-sources.jar', [('a/A.java', A_JAVA)])
        self.archives[0]['sha256'] = '0' * 64
        self.document('a-1.0/A.java.txt', b'outdated', jar + '!/a/A.java')
        self.document('same.txt', b'same', self.upstream_file('same', b'same'))
        manual = {'schemaVersion': 1, 'components': [{'id': 'maven:a:a@1.0', 'documents': [
            {'path': OUT + '/a-1.0/A.java.txt', 'sha256': sha256(b'outdated'), 'kind': 'license'},
            {'path': 'tools/workbench/other.js', 'sha256': 'untouched', 'kind': 'license'}]}]}
        (self.repo / MANUAL).write_text(json.dumps(manual, indent=2) + '\n')
        result = self.run_script('--update-hashes')
        self.assertEqual(result.returncode, 0, result.stderr)
        manifest = json.loads((self.repo / MANIFEST).read_text())
        self.assertEqual(manifest['archives'][0]['sha256'], sha256((self.upstream / 'a-sources.jar').read_bytes()))
        self.assertEqual(manifest['documents'][0]['sha256'], sha256(A_JAVA))
        self.assertEqual(manifest['documents'][1]['sha256'], sha256(b'same'))
        documents = json.loads((self.repo / MANUAL).read_text())['components'][0]['documents']
        self.assertEqual(documents[0]['sha256'], sha256(A_JAVA))
        self.assertEqual(documents[1]['sha256'], 'untouched')
        self.assertEqual(self.output('a-1.0/A.java.txt'), A_JAVA)
        self.assertEqual(subprocess.run([sys.executable, str(SCRIPT), '--repo', str(self.repo), '--check'],
                                        capture_output=True).returncode, 0)

