class RepositoryManifestTest(unittest.TestCase):
    def test_manual_inventory_hashes_match_the_build_manifest(self):
        manifest = json.loads((ROOT / MANIFEST).read_text())
        pinned = {document['path']: document['sha256'] for document in manifest['documents']}
        self.assertEqual(len(pinned), len(manifest['documents']))
        manual = json.loads((ROOT / MANUAL).read_text())
        referenced = [document for component in manual['components'] for document in component.get('documents', [])
                      if document['path'].startswith(OUT + '/')]
        self.assertTrue(referenced)
        for document in referenced:
            self.assertEqual(pinned.get(document['path']), document['sha256'], document['path'])

    def test_every_archive_backed_document_uses_a_pinned_archive(self):
        manifest = json.loads((ROOT / MANIFEST).read_text())
        archives = {archive['url'] for archive in manifest['archives']}
        for document in manifest['documents']:
            if '!/' in document['source'] or document.get('recipe', '').startswith('source-notice'):
                self.assertIn(document['source'].split('!/')[0], archives, document['path'])
            self.assertTrue(document['source'].startswith('https://'), document['path'])

    def test_generated_evidence_is_not_tracked(self):
        self.assertIn('/' + OUT + '/\n', (ROOT / '.gitignore').read_text())
        try:
            tracked = subprocess.run(['git', 'ls-files', '--', OUT], cwd=ROOT, capture_output=True, text=True)
        except FileNotFoundError:
            self.skipTest('git is not available')
        self.assertEqual(tracked.stdout, '')


